from utils.config import Config


class Highlighter:
    def __init__(self, config: Config):
        self.__config = config

    @staticmethod
    def __get_lexer(code):
        try:
            lexer = get_lexer_by_name(Config.LANGUAGE)
        except ClassNotFound:
            lexer = get_lexer_by_name("python")

        return lexer

    def highlight_code(self, code):
        lexer = self.__get_lexer(code)
        formatter = HtmlFormatter(style=Config.STYLE)

        return highlight(code, lexer, formatter)

    def highlight_ast(self, ast_node):
        source = ast.dump(ast_node)
        return self.highlight_code(source)

    def highlight_file(self, filepath: Path):
        with open(filepath, "r", encoding="utf-8") as f:
            code = f.read()
        return self.highlight_code(code)
